"""
Functions used by the parser for exporting to C#
"""

from ..constants.char_ability import Team

FILE_HEADER = \
"""// THIS FILE IS AUTOMATICALLY GENERATED

using System.Numerics;
using Sonic_Heroes_AP_Client.Definitions;
using Sonic_Heroes_AP_Client.StageObj;
using Sonic_Heroes_AP_Client.Sanity.Enemy;

namespace Sonic_Heroes_AP_Client.Sanity."""

TAB_CHAR: str = "    "


DEFAULT_RECORD_PARAMS: list[str] = \
[
    "Team Team",
    "LevelId LevelId",
    "string Region",
    "string LocName",
    "int Group",
    "int IdOffsetGroup",
    "int IdOffsetFull",
    "byte LinkID",
    "Vector3 SpawnCoords",
]


DEFAULT_RECORD_PARENT_PARAMS: list[str] = \
[
    "Team: Team",
    "LevelId: LevelId",
    "Region: Region",
    "LocName: LocName",
    "Group: Group",
    "IdOffsetGroup: IdOffsetGroup",
    "IdOffsetFull: IdOffsetFull",
    "LinkID: LinkID",
    "SpawnCoords: SpawnCoords",
]



# file/class name (TripleSpringsData)
# StageObjTypes name (StageObjTypes.TripleSpring)
# record class name (TripleSpringData)
# record parent class name (StageObjBase / EnemyData.BaseEnemyData)
# namespace name (TripleSprings)



def get_file_header(namespace_class_name: str) -> str:
    _result: str = f"{FILE_HEADER}{namespace_class_name};\n\n"
    _result += f"public static class {namespace_class_name}Data\n{{\n"
    return _result

def get_file_footer() -> str:
    return f"\n}}\n"



def get_parsed_export_record_class_definition(record_class_name: str, record_parent_class: str, stage_obj_type: str, custom_record_vars: list[str]) -> str:
    _result: str = f"{TAB_CHAR}public record {record_class_name}("
    for custom_variable in custom_record_vars:
        _result += f"{custom_variable}, "
    for index, default_variable in enumerate(DEFAULT_RECORD_PARAMS):
        if index > 0:
            _result += ", "
        _result += f"{default_variable}"

    _result += f") : {record_parent_class}("

    for index, default_variable in enumerate(DEFAULT_RECORD_PARENT_PARAMS):
        if index > 0:
            _result += ", "
        _result += f"{default_variable}"
    _result += f", StageObjType: StageObjTypes.{stage_obj_type});\n\n"

    return _result



def get_parsed_export_entry_list_str(file_class_name: str, record_class_name: str, team: str, parsed_entries_params: list[dict[str, str]]) -> str:
    _result: str = f"{TAB_CHAR}public static readonly List<{record_class_name}> {team}{file_class_name} = "
    _result += f"\n{TAB_CHAR}[\n"

    for entry in parsed_entries_params:
        _result += f"{TAB_CHAR}{TAB_CHAR}new {record_class_name}("
        for index, (param_key, param_value) in enumerate(entry.items()):
            if index > 0:
                _result += ", "
            _result += f"{param_key}: {param_value}"

        _result += "),\n"

    if len(parsed_entries_params) < 1:
        _result += f"{TAB_CHAR}{TAB_CHAR}\n"

    _result += f"{TAB_CHAR}];\n\n"
    return _result


def get_all_lists_concatenated(file_class_name: str, record_class_name: str) -> str:
    _result: str = f"{TAB_CHAR}public static readonly List<{record_class_name}> All{file_class_name} = "
    # funny_flag: bool = False
    #
    # for team in Team:
    #     if team is Team.ANY_TEAM:
    #         continue
    #     if funny_flag:
    #         _result += f".Concat({team.value}{file_class_name})"
    #     else:
    #         _result += f"{team.value}{file_class_name}"
    #         funny_flag = True
    #
    # _result += ".ToList();\n\n"

    _result += f"\n{TAB_CHAR}[\n"

    for team in Team:
        if team is Team.ANY_TEAM:
            continue
        _result += f"{TAB_CHAR}{TAB_CHAR}.. {team.value}{file_class_name}, \n"

    _result += f"{TAB_CHAR}];\n\n"
    return _result






def get_parsed_export_entry_str(entry_class_name: str, params: dict[str, str]) -> str:
    raise ValueError("Not implemented")
    _result: str = f"new {entry_class_name}("

    for key, value in params.items():
        _result += f"{key}: {value}, "
    if _result[-2:] == ", ":
        _result = _result[:-2]

    _result += ")"
    return _result



